proc invoke*(route: ptr LogosRouteHandle, request: ShapesReflectRequest): Result[ShapesReflectResponse, InvocationFailure] =
  ## `shapes.reflect` through `route` (INTERFACE §5.2).
  let p0 = route
  let params = encodeCbor(toCbor(request))
  let v = ?routeCall(p0, "reflect", params, callsSchema(), "shapes.reflect_response")
  ok(fromChecked(ShapesReflectResponse, v))

